  Lemma seg_T4 : forall s msF mo regs mem (N PL CP r D : word) K,
    regs118 regs N PL D CP -> getr regs 21 = r ->
    stk_ok RSEGS mem sp 80 -> aro_none mem -> arelro_none mem -> latch_ok mem ->
    (forall regs' msF' mo',
        as_VIS H s msF' = mkst regs' (Z_to_bv 64 0xa4324) mem rom -> as_AKREL H s (mkCfg msF' mo') -> same_but_materialized mo mo' ->
        loop_base regs' N D D -> getr regs' 21 = r -> getr regs' 19 = CP ->
        keep4 regs regs' ->
        realizes bsegs (mkCfg msF' mo') K) ->
    as_VIS H s msF = mkst regs (Z_to_bv 64 0xa42e4) mem rom -> as_AKREL H s (mkCfg msF mo) ->
